package uk.ac.ravensbourne.casevault.web;
import java.util.UUID; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.stereotype.Controller; import org.springframework.web.bind.annotation.*; import uk.ac.ravensbourne.casevault.security.UserPrincipal; import uk.ac.ravensbourne.casevault.service.CaseAccessService;
@Controller @RequestMapping("/cases") public class CaseController { private final CaseAccessService access; public CaseController(CaseAccessService access){this.access=access;} @GetMapping("/{id}") @PreAuthorize("isAuthenticated()") @ResponseBody public String view(@AuthenticationPrincipal UserPrincipal principal,@PathVariable UUID id){return access.requireView(principal,id).getId().toString();} }
